contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sentinel) public payable {
        uint before;
        uint afterVal;
        bool reverted;
        address newOwner = address(uint160(sentinel));

        before = uint(uint160(c.owner()));

        bool success = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            require(success);
        }

        afterVal = uint(uint160(c.owner()));

        assert((!reverted && afterVal == uint(uint160(newOwner))) || (reverted && afterVal == before));
    }

    receive() external payable {}
}

