// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(uint256 sentinel) internal {
        uint before;
        uint afterVal;
        bool reverted;
        address newOwner = address(uint160(sentinel));
        before = uint(uint160(c.owner()));
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            require(success);
        } catch {
            reverted = true;
        }
        afterVal = uint(uint160(c.owner()));
        assertTrue((!reverted && afterVal == uint(uint160(newOwner))) || (reverted && afterVal == before));
    }

    function testFuzz_run(uint256 sentinel) public {
        _run(sentinel);
    }

    receive() external payable {}
}
